import{_ as o,C as a,o as i,c as l,j as s,a as u,E as n,a2 as t}from"./chunks/framework.CdvW4CUT.js";const q=JSON.parse('{"title":"Graphe","description":"","frontmatter":{"title":"Graphe"},"headers":[],"relativePath":"guide/graph.md","filePath":"guide/graph.md"}'),p={name:"guide/graph.md"};function c(g,e,d,h,m,v){const r=a("Capture");return i(),l("div",null,[e[0]||(e[0]=s("h1",{id:"graphe",tabindex:"-1"},[u("Graphe "),s("a",{class:"header-anchor",href:"#graphe","aria-label":'Permalink to "Graphe"'},"​")],-1)),e[1]||(e[1]=s("p",null,"Le graphe dessine votre mémoire comme un réseau : chaque point est un domaine, un concept, un projet ou une note, chaque trait une relation entre deux d'entre eux. Il se parcourt à la souris comme au clavier, et se met à jour tout seul quand la mémoire change.",-1)),n(r,{name:"graphe",alt:"Le graphe de la mémoire en thème sombre : un nœud sélectionné au clavier, ses relations (plus général, plus précis, voisines) listées à droite."}),e[2]||(e[2]=t('<h2 id="ce-que-vous-voyez" tabindex="-1">Ce que vous voyez <a class="header-anchor" href="#ce-que-vous-voyez" aria-label="Permalink to &quot;Ce que vous voyez&quot;">​</a></h2><p>Le graphe s&#39;ouvre dans son propre onglet, <strong>Graphe</strong> (voir <a href="/guide/home.html">Accueil</a> pour y arriver).</p><ul><li><strong>L&#39;en-tête</strong> : le titre « La mémoire en relations », le champ <strong>Chercher une note, un projet…</strong>, et deux boutons, <strong>Voir en liste</strong> et <strong>Fiche</strong>.</li><li><strong>La barre de filtres</strong> : la ligne <strong>NIVEAUX</strong> avec une puce par niveau et son nombre de points (<strong>Domaine</strong>, <strong>Concept</strong>, <strong>Projet</strong>, <strong>Note</strong>, <strong>Archives</strong>), les menus <strong>Appartenance</strong> et <strong>Relations</strong>, la puce <strong>Non classées</strong> et le bouton <strong>Réinitialiser</strong>.</li><li><strong>Le dessin</strong> : un point par élément, un trait par relation. Une légende en bas à gauche nomme les niveaux. En bas à droite, « Titres affichés : 14 sur 14 » dit combien d&#39;étiquettes tiennent à l&#39;écran, et trois boutons règlent le zoom (<strong>Éloigner</strong>, <strong>Approcher</strong>, <strong>Tout voir</strong>).</li><li><strong>La fiche</strong>, dans la colonne de droite : <ul><li>Sans sélection, elle rappelle les touches : « Flèches haut et bas : monter ou descendre. Flèches gauche et droite : passer à une voisine. Entrée : ouvrir la note. »</li><li>Avec un point choisi, elle affiche « Sélection : … », son niveau (« Projet · Archives de sessions : 4 »), le bouton <strong>Ouvrir la note</strong>, puis ses relations en trois groupes avec leur nombre : <strong>Plus général</strong>, <strong>Plus précis</strong> et <strong>Voisines</strong>.</li></ul></li></ul><p>Les sessions d&#39;archives ne sont pas dessinées par défaut : elles sont « repliées dans leur projet », et la puce <strong>Archives</strong> en donne le nombre.</p><p>Quand la mémoire a moins de trois relations, il n&#39;y a rien à dessiner. L&#39;écran le dit : « Rien à relier pour l&#39;instant. Rangez des notes sous un projet, un domaine ou un concept, et leurs liens apparaîtront ici. » Si la lecture échoue, il l&#39;indique (« Les relations n&#39;ont pas pu être lues. ») et propose de réessayer.</p><h2 id="ce-que-vous-pouvez-faire" tabindex="-1">Ce que vous pouvez faire <a class="header-anchor" href="#ce-que-vous-pouvez-faire" aria-label="Permalink to &quot;Ce que vous pouvez faire&quot;">​</a></h2><h3 id="choisir-un-point" tabindex="-1">Choisir un point <a class="header-anchor" href="#choisir-un-point" aria-label="Permalink to &quot;Choisir un point&quot;">​</a></h3><p>Cliquez un point : il est sélectionné, et la fiche affiche ses relations. Dans la fiche, un clic sur le nom d&#39;une relation déplace la sélection sur celle-ci.</p><p>Au clavier, placez le focus sur le dessin (Tab, ou un clic), puis :</p><ul><li><strong>↑</strong> monte vers un élément plus général (le premier de la liste <strong>Plus général</strong>), <strong>↓</strong> descend vers un plus précis ;</li><li><strong>←</strong> et <strong>→</strong> passent à une voisine ;</li><li>le premier appui choisit l&#39;élément le plus relié parmi les domaines, concepts et projets ;</li><li><strong>Échap</strong> retire la sélection.</li></ul><h3 id="ouvrir-la-note-d-un-point" tabindex="-1">Ouvrir la note d&#39;un point <a class="header-anchor" href="#ouvrir-la-note-d-un-point" aria-label="Permalink to &quot;Ouvrir la note d&#39;un point&quot;">​</a></h3><p>Double-cliquez le point, tapez <strong>Entrée</strong> quand il est sélectionné, ou cliquez <strong>Ouvrir la note</strong> dans la fiche. La note s&#39;ouvre dans un onglet (<a href="/guide/atom.html">Atome et éditeur</a>).</p><h3 id="deplacer-le-dessin" tabindex="-1">Déplacer le dessin <a class="header-anchor" href="#deplacer-le-dessin" aria-label="Permalink to &quot;Déplacer le dessin&quot;">​</a></h3><p>Glissez un point pour le déplacer : il reste là où vous le tenez et le reste du réseau se réorganise autour. Glissez le fond pour faire défiler le dessin.</p><h3 id="zoomer" tabindex="-1">Zoomer <a class="header-anchor" href="#zoomer" aria-label="Permalink to &quot;Zoomer&quot;">​</a></h3><ul><li>Les boutons <strong>Approcher</strong> (+), <strong>Éloigner</strong> (−) et <strong>Tout voir</strong> (⤢), en bas à droite du dessin.</li><li><strong>⌘</strong> (ou <strong>Ctrl</strong>) et la molette, ou le pincement du pavé tactile. La molette seule ne zoome qu&#39;une fois le dessin pris au clavier : sinon elle fait défiler la page.</li></ul><h3 id="chercher-une-note" tabindex="-1">Chercher une note <a class="header-anchor" href="#chercher-une-note" aria-label="Permalink to &quot;Chercher une note&quot;">​</a></h3><p>Cliquez le champ <strong>Chercher une note, un projet…</strong>, ou tapez <strong>/</strong> (hors d&#39;un champ de saisie).</p>',18)),n(r,{name:"graphe-recherche",alt:"La recherche du graphe : deux lettres saisies, les notes et projets qui correspondent sont proposés avec leur niveau."}),e[3]||(e[3]=t('<ul><li>Les résultats s&#39;affichent au fil de la frappe, avec leur nombre (« Résultats : 3 »). Les points trouvés sont cerclés dans le dessin.</li><li><strong>↑</strong> et <strong>↓</strong> parcourent la liste. <strong>Entrée</strong> centre le dessin sur le résultat et le sélectionne. <strong>⇧ Entrée</strong> ouvre la note.</li><li><strong>Échap</strong> ferme la liste, un second <strong>Échap</strong> vide le champ.</li><li>Un résultat écarté par un filtre reste dans la liste, atténué (« écarté par les filtres »). <strong>Les montrer</strong> lève les filtres.</li><li>Sans résultat : « Aucune note ne correspond à … », avec le conseil d&#39;essayer moins de lettres ou un mot du titre.</li></ul><h3 id="filtrer" tabindex="-1">Filtrer <a class="header-anchor" href="#filtrer" aria-label="Permalink to &quot;Filtrer&quot;">​</a></h3><p>Les filtres se combinent : un point doit passer tous ceux que vous avez posés.</p>',3)),n(r,{name:"graphe-filtres",alt:"Le filtre « Appartenance » du graphe, ouvert : « Éclairage » est coché, les notes qui n'y appartiennent pas sont grisées."}),e[4]||(e[4]=t('<ul><li><strong>Niveaux</strong> : cliquez une puce pour retirer ou remettre un niveau. La puce <strong>Archives</strong> déplie les sessions d&#39;archives dans le dessin ; la lecture est alors refaite.</li><li><strong>Appartenance</strong> : un menu avec un champ <strong>Un projet ou un domaine</strong> et une case par projet ou domaine. Cocher des cases ne garde que ces éléments et ce qui en descend.</li><li><strong>Relations</strong> : <strong>Toutes</strong>, <strong>3 ou plus</strong>, <strong>10 ou plus (les hubs)</strong> ou <strong>Sans relation</strong>, selon le nombre de relations de chaque point.</li><li><strong>Non classées</strong> : ne garde que les notes, concepts et projets qui n&#39;ont aucun parent.</li><li><strong>Éléments écartés</strong> : dès qu&#39;un filtre est posé, choisissez <strong>Griser</strong> (les points écartés restent en place, très pâles) ou <strong>Masquer</strong> (ils disparaissent et le dessin se réorganise). Une ligne dit combien ont été grisés ou masqués.</li><li><strong>Réinitialiser (N)</strong> retire les N filtres posés.</li></ul><h3 id="voir-la-memoire-en-liste" tabindex="-1">Voir la mémoire en liste <a class="header-anchor" href="#voir-la-memoire-en-liste" aria-label="Permalink to &quot;Voir la mémoire en liste&quot;">​</a></h3><p><strong>Voir en liste</strong> remplace le dessin par une liste des notes et relations, rangée par niveau puis par ordre alphabétique. La sélection, la recherche, les filtres et la fiche restent les mêmes. <strong>Voir le graphe</strong> revient au dessin. Votre choix est retenu sur cet ordinateur.</p><p>Dans une fenêtre trop étroite pour le dessin, la liste s&#39;impose.</p><h3 id="replier-la-fiche" tabindex="-1">Replier la fiche <a class="header-anchor" href="#replier-la-fiche" aria-label="Permalink to &quot;Replier la fiche&quot;">​</a></h3><p>Le bouton <strong>Fiche</strong>, ou la touche <strong>F</strong> (hors d&#39;un champ de saisie), replie ou rouvre la colonne de droite pour laisser toute la place au dessin.</p><h3 id="laisser-le-graphe-suivre-la-memoire" tabindex="-1">Laisser le graphe suivre la mémoire <a class="header-anchor" href="#laisser-le-graphe-suivre-la-memoire" aria-label="Permalink to &quot;Laisser le graphe suivre la mémoire&quot;">​</a></h3><p>Rien à faire : quand la mémoire change (un agent écrit, vous modifiez une note), le graphe se relit en quelques secondes. Si vous passez à un autre onglet, le graphe garde sa place, son zoom, sa sélection, ses filtres et sa recherche pour votre retour.</p>',8))])}const b=o(p,[["render",c]]);export{q as __pageData,b as default};
